import React, { useState } from 'react';

function PaymentScreen({ ticketTotal = 0, comboTotal = 0, onBack, onConfirm }) {
  const methods = ['MoMo', 'ZaloPay', 'QR'];
  const [method, setMethod] = useState(methods[0]);

  const total = ticketTotal + comboTotal;

  return (
    <div>
      <button className="btn mb-4 fw-bold text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }} onClick={onBack}>⬅ Quay lại chọn combo</button>

      <div className="card p-4 shadow-sm border-0 bg-white" style={{ backgroundColor: '#faf5ff' }}>
        <h3 className="fw-bold mb-3" style={{ color: '#7c3aed' }}>Chọn phương thức thanh toán</h3>

        <div className="mb-3">
          {methods.map(m => (
            <div key={m} className="form-check mb-2">
              <input className="form-check-input" type="radio" name="pay" id={`pay-${m}`} checked={method===m} onChange={() => setMethod(m)} />
              <label className="form-check-label ms-2" htmlFor={`pay-${m}`} style={{ color: '#6b7280' }}>{m}</label>
            </div>
          ))}
        </div>

        <div className="border-top pt-3 mt-3 d-flex justify-content-between align-items-center">
          <div className="text-secondary">Tổng Vé + Combo:</div>
          <div className="fs-4 fw-bold" style={{ color: '#7c3aed' }}>{total.toLocaleString()}đ</div>
        </div>

        <button className="btn w-100 fw-bold mt-4 py-3 text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)' }} onClick={() => {
          // Generate a fake QR code if QR method selected
          if (method === 'QR') {
            const code = Math.floor(100000 + Math.random() * 900000).toString();
            onConfirm({ method, total, qrCode: code });
          } else {
            onConfirm({ method, total });
          }
        }}>Thanh toán giả lập</button>
      </div>
    </div>
  );
}

export default PaymentScreen;
